import sys, re
def parse(path):
    lines=open(path, encoding='utf-8').read().split('\n')
    grid=[]
    for l in lines:
        cells=[]; fg=None;bg=None;bold=False;under=False;rev=False
        i=0
        while i < len(l):
            if l[i]=='\x1b':
                m=re.match(r'\x1b\[([0-9;]*)m', l[i:])
                if m:
                    p=m.group(1)
                    for tok in p.split(';'):
                        if tok=='0': fg=None;bg=None;bold=False
                        elif tok=='1': bold=True
                        elif tok=='2': fg='dim'
                        elif tok=='3': fg='italic'
                        elif tok=='4': under=True
                        elif tok=='7': rev=True
                        elif tok=='22': bold=False
                        elif tok=='23': fg=None
                        elif tok=='24': under=False
                        elif tok=='27': rev=False
                        elif tok=='39': fg=None
                        elif tok=='49': bg=None
                        elif tok.startswith('38;5;'): fg=int(tok.split(';')[2])
                        elif tok.startswith('48;5;'): bg=int(tok.split(';')[2])
                        elif tok.startswith('38;2;'):
                            v=tok.split(';'); fg=(int(v[2]),int(v[3]),int(v[4]))
                        elif tok.startswith('48;2;'):
                            v=tok.split(';'); bg=(int(v[2]),int(v[3]),int(v[4]))
                    i+=m.end(); continue
                else:
                    m2=re.match(r'\x1b.', l[i:])
                    if m2: i+=m2.end(); continue
            cells.append((l[i], fg,bg,bold,under,rev))
            i+=1
        grid.append(cells)
    return grid
def show(g, cols=None):
    for r,row in enumerate(g):
        out=''
        for c in row[:cols]:
            ch,fg,bg,b,u,rv=c
            out+=ch
        print('%2d |%s|'%(r,out))
    print()
def detail(g, r, c0=0, c1=None):
    row=g[r]
    c1 = c1 if c1 is not None else len(row)
    for i in range(c0,min(c1,len(row))):
        ch,fg,bg,b,u,rv=row[i]
        if ch==' ': 
            pass
        print(i, repr(ch), 'fg=%s bg=%s'%(fg,bg), 'bold' if b else '')
