use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct RefreshConfig {
    pub auto_refresh: bool,
    pub refresh_interval: u64,
    pub auto_fetch: bool,
    pub fetch_interval: u64,
}

impl Default for RefreshConfig {
    fn default() -> Self {
        Self { auto_refresh: true, refresh_interval: 10, auto_fetch: true, fetch_interval: 60 }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Config {
    pub refresh: RefreshConfig,
}

impl Config {
    pub fn load() -> Self {
        let mut cfg = Self::default();
        if let Some(path) = config_path() {
            if let Ok(text) = std::fs::read_to_string(&path) {
                if let Ok(value) = text.parse::<toml::Table>() {
                    if let Some(t) = value.get("refresh").and_then(|v| v.as_table()) {
                        if let Some(v) = t.get("auto_refresh").and_then(toml::Value::as_bool) {
                            cfg.refresh.auto_refresh = v;
                        }
                        if let Some(v) = t.get("refresh_interval").and_then(toml::Value::as_integer) {
                            cfg.refresh.refresh_interval = v.max(1) as u64;
                        }
                        if let Some(v) = t.get("auto_fetch").and_then(toml::Value::as_bool) {
                            cfg.refresh.auto_fetch = v;
                        }
                        if let Some(v) = t.get("fetch_interval").and_then(toml::Value::as_integer) {
                            cfg.refresh.fetch_interval = v.max(10) as u64;
                        }
                    }
                }
            }
        }
        cfg
    }
}

fn config_path() -> Option<PathBuf> {
    let home = std::env::var_os("HOME")?;
    let mut p = PathBuf::from(home);
    p.push(".config");
    p.push("keifu");
    p.push("config.toml");
    Some(p)
}
EOF
