use anyhow::{anyhow, Context, Result};
use git2::{BranchType, Delta, DiffOptions, Oid, Patch, Repository, Sort};
use std::collections::HashMap;

/// A commit as displayed by keifu.
#[derive(Debug, Clone)]
pub struct Commit {
    pub id: Oid,
