    pub parents: Vec<Oid>,
}

pub fn short_of(id: &Oid) -> String {
    let s = id.to_string();
    s.chars().take(7).collect()
}

/// A branch (local or remote-tracking) reference.
#[derive(Debug, Clone)]
pub struct BranchRef {
    /// Display name, e.g. `main` or `origin/feature`
    pub name: String,
    /// Remote name when this is a remote-tracking ref (e.g. `origin`)
    pub remote: Option<String>,
    /// Name without the remote prefix, e.g. `feature`
    pub local_name: String,
    pub tip: Oid,
}

impl BranchRef {
    pub fn is_remote(&self) -> bool {
