fn walk_tree(
    repo: &Repository,
    tree: &git2::Tree,
    prefix: &str,
    map: &mut HashMap<String, Oid>,
) -> Result<()> {
    for i in 0..tree.len() {
        let entry = match tree.get(i) {
            Some(e) => e,
            None => continue,
        };
        let name = entry.name().unwrap_or("").to_string();
        let path = if prefix.is_empty() { name } else { format!("{}/{}", prefix, name) };
        match entry.kind() {
            Some(git2::ObjectType::Tree) => {
                let sub = entry.to_object(repo)?.peel_to_tree()?;
                walk_tree(repo, &sub, &path, map)?;
            }
            _ => {
                map.insert(path, entry.id());
            }
        }
    }
    Ok(())
}

fn tree_paths(repo: &Repository, tree: &git2::Tree) -> Result<HashMap<String, Oid>> {
    let mut map = HashMap::new();
    walk_tree(repo, tree, "", &mut map)?;
    Ok(map)
}

/// Collect line add/remove counts for `path` between the two trees.
fn line_counts(
    repo: &Repository,
    old_map: &HashMap<String, Oid>,
    new_map: &HashMap<String, Oid>,
    path: &str,
) -> Result<Option<(u64, u64)>> {
    let old_oid = old_map.get(path);
    let new_oid = new_map.get(path);
    if old_oid.is_none() && new_oid.is_none() {
        return Ok(None);
    }
    let old_blob = match old_oid {
        Some(oid) => Some(repo.find_blob(*oid, None)?),
        None => None,
    };
    let new_blob = match new_oid {
        Some(oid) => Some(repo.find_blob(*oid, None)?),
        None => None,
    };
    // Binary content => no line statistics
    for b in [&old_blob, &new_blob] {
        if let Some(b) = b {
            if let Ok(Some(content)) = b.content() {
                if content.contains(&0u8) {
                    return Ok(None);
                }
            }
        }
    }
    let patch = match (old_blob, new_blob) {
        (Some(o), Some(n)) => Patch::from_blobs(
            Some(o),
            Some(std::path::Path::new(path)),
            Some(n),
            Some(std::path::Path::new(path)),
            None,
        )?,
        (Some(o), None) => Patch::from_blob_and_buffer(
            Some(o),
            Some(std::path::Path::new(path)),
            &[],
            Some(std::path::Path::new(path)),
            None,
        )?,
        (None, Some(n)) => Patch::from_blob_and_buffer(
            None,
            Some(std::path::Path::new(path)),
            Some(n),
            Some(std::path::Path::new(path)),
            None,
        )?,
        (None, None) => return Ok(None),
    };
    let (_ctx, add, del) = patch.line_stats()?;
    Ok(Some((add as u64, del as u64)))
}

fn kind_of(delta: Delta) -> ChangeKind {
    match delta {
        Delta::Added => ChangeKind::Added,
        Delta::Deleted => ChangeKind::Deleted,
        Delta::Modified => ChangeKind::Modified,
        Delta::Renamed => ChangeKind::Renamed,
        Delta::Typechange => ChangeKind::Typechange,
        Delta::Conflicted => ChangeKind::Conflicted,
        Delta::Untracked => ChangeKind::Untracked,
        _ => ChangeKind::Other,
    }
}

/// Build the changed-file list for the difference between two trees.
fn changed_files(
    repo: &Repository,
    old_tree: Option<&git2::Tree>,
    new_tree: &git2::Tree,
    skip_untracked: bool,
) -> Result<Vec<FileChange>> {
    let old_map = match old_tree {
        Some(t) => tree_paths(repo, t)?,
        None => HashMap::new(),
    };
    let new_map = tree_paths(repo, new_tree)?;
    let mut opts = DiffOptions::new();
    if skip_untracked {
        opts.include_untracked(false);
    }
    let diff = repo.diff_tree_to_tree(old_tree, Some(new_tree), Some(&mut opts))?;
    let mut out: Vec<FileChange> = Vec::new();
    let mut seen: HashMap<String, ()> = HashMap::new();
    for delta in diff.deltas() {
        let kind = kind_of(delta.status());
        if skip_untracked && kind == ChangeKind::Untracked {
            continue;
        }
        let path = delta
            .new_file()
            .path()
            .map(|p| p.to_string_lossy().to_string())
            .or_else(|| delta.old_file().path().map(|p| p.to_string_lossy().to_string()))
            .unwrap_or_default();
        let counted = !seen.contains_key(&path);
        seen.insert(path.clone(), ());
        let (added, removed) = if counted {
            match line_counts(repo, &old_map, &new_map, &path)? {
                Some((a, d)) if a != 0 || d != 0 => (Some(a), Some(d)),
                _ => (None, None),
            }
        } else {
            (None, None)
        };
        out.push(FileChange { path, kind, added, removed });
        if out.len() >= 50 {
            break;
        }
    }
    Ok(out)
}

/// Load all information needed to render the UI.
pub fn load() -> Result<RepoData> {
    let repo = Repository::discover(".").context("Git repository not found. Please run inside a Git repository.")?;
    let workdir = repo
        .workdir()
        .ok_or_else(|| anyhow!("repository has no working directory"))?;
    let name = workdir
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_default();

    // commits in revwalk order
    let mut commits: Vec<Commit> = Vec::new();
    let mut revwalk = repo.revwalk()?;
    revwalk.set_sorting(Sort::TIME | Sort::TOPOLOGICAL)?;
    revwalk.push_glob("refs/heads/*")?;
    revwalk.push_glob("refs/remotes/*")?;
    for oid in revwalk {
        let oid = oid?;
        let commit = repo.find_commit(oid)?;
        let summary = commit.summary().unwrap_or(None).unwrap_or("").to_string();
        let body = commit.message().unwrap_or(None).unwrap_or("").to_string();
        let author = commit.author().name().unwrap_or(None).unwrap_or("").to_string();
        let email = commit.author().email().unwrap_or(None).unwrap_or("").to_string();
        let mut parents = Vec::new();
        for i in 0..commit.parent_count() {
            if let Ok(p) = commit.parent_id(i) {
                parents.push(p);
            }
        }
        commits.push(Commit {
            id: oid,
            short: short_of(&oid),
            summary,
            body,
            author,
            email,
            time: commit.time().seconds(),
            parents,
        });
    }

    // branches: locals first then remotes, each sorted by name
    let mut branches: Vec<BranchRef> = Vec::new();
    for res in repo.branches(Some(BranchType::Local))? {
        let (branch, _) = res?;
        let name = branch.name()?.unwrap_or("").to_string();
        let tip = branch.get().target().resolve()?.target_id()?;
        branches.push(BranchRef { name: name.clone(), remote: None, local_name: name, tip });
    }
    for res in repo.branches(Some(BranchType::Remote))? {
        let (branch, _) = res?;
        let full = branch.name()?.unwrap_or("").to_string();
        let (remote, local) = match full.split_once('/') {
            Some((r, l)) => (r.to_string(), l.to_string()),
            None => (String::new(), full.clone()),
        };
        let tip = branch.get().target().resolve()?.target_id()?;
        branches.push(BranchRef { name: full, remote: Some(remote), local_name: local, tip });
    }
    branches.sort_by(|a, b| a.name.cmp(&b.name));

    let head_commit = repo.head().ok().and_then(|h| h.target()).and_then(|t| {
        repo.find_commit(t).ok().map(|c| c.id())
    });
    let head_branch = repo.head().ok().and_then(|h| h.shorthand().ok().map(|s| s.to_string()));

    let has_origin = repo.remotes()?.iter().any(|r| r == "origin");

    // working tree changes
    let head_tree = head_commit.and_then(|id| repo.find_commit(id).ok()).and_then(|c| c.tree().ok());
    let dirty = match head_tree {
        Some(tree) => {
            let mut d = changed_files_workdir(&repo, &tree)?;
            d
        }
        None => Vec::new(),
    };

    Ok(RepoData { name, commits, branches, head_commit, head_branch, dirty, has_origin })
}

fn changed_files_workdir(repo: &Repository, tree: &git2::Tree) -> Result<Vec<FileChange>> {
    let head_map = tree_paths(repo, tree)?;
    let mut opts = DiffOptions::new();
    let diff = repo.diff_tree_to_workdir_with_index(Some(tree), Some(&mut opts))?;
    let mut out: Vec<FileChange> = Vec::new();
    let mut seen: HashMap<String, ()> = HashMap::new();
    for delta in diff.deltas() {
        let kind = kind_of(delta.status());
        if kind == ChangeKind::Untracked || kind == ChangeKind::Ignored {
            continue;
        }
        let path = delta
            .new_file()
            .path()
            .map(|p| p.to_string_lossy().to_string())
            .or_else(|| delta.old_file().path().map(|p| p.to_string_lossy().to_string()))
            .unwrap_or_default();
        // resolve worktree/index content
        let counted = !seen.contains_key(&path);
        seen.insert(path.clone(), ());
        let (added, removed) = if counted {
            match workdir_counts(repo, &head_map, &path)? {
                Some((a, d)) if a != 0 || d != 0 => (Some(a), Some(d)),
                _ => (None, None),
            }
        } else {
            (None, None)
        };
        out.push(FileChange { path, kind, added, removed });
        if out.len() >= 50 {
            break;
        }
    }
    Ok(out)
}

/// Line counts between HEAD and the index/worktree for `path`.
fn workdir_counts(
    repo: &Repository,
    head_map: &HashMap<String, Oid>,
    path: &str,
) -> Result<Option<(u64, u64)>> {
    let head_blob = match head_map.get(path) {
        Some(oid) => Some(repo.find_blob(*oid, None)?),
        None => None,
    };
    // index version (staged) or worktree version
    let other = index_or_worktree_blob(repo, path)?;
    for b in [&head_blob, &other] {
        if let Some(b) = b {
            if let Ok(Some(content)) = b.content() {
                if content.contains(&0u8) {
                    return Ok(None);
                }
            }
        }
    }
    let patch = match (head_blob, other) {
        (Some(o), Some(n)) => Patch::from_blobs(
            Some(o),
            Some(std::path::Path::new(path)),
            Some(n),
            Some(std::path::Path::new(path)),
            None,
        )?,
        (Some(o), None) => Patch::from_blob_and_buffer(
            Some(o),
            Some(std::path::Path::new(path)),
            &[],
            Some(std::path::Path::new(path)),
            None,
        )?,
        (None, Some(n)) => Patch::from_blob_and_buffer(
            None,
            Some(std::path::Path::new(path)),
            Some(n),
            Some(std::path::Path::new(path)),
            None,
        )?,
        (None, None) => return Ok(None),
    };
    let (_ctx, add, del) = patch.line_stats()?;
    Ok(Some((add as u64, del as u64)))
}

/// Read the current content of `path`: from the index if staged, else the worktree.
fn index_or_worktree_blob(repo: &Repository, path: &str) -> Result<Option<git2::Blob>> {
    let index = repo.index()?;
    if let Some(entry) = index.get_path(std::path::Path::new(path), 0) {
        if let Ok(blob) = repo.find_blob(entry.id, None) {
            return Ok(Some(blob));
        }
    }
    if let Some(workdir) = repo.workdir() {
        let full = workdir.join(path);
        if let Ok(data) = std::fs::read(&full) {
            let oid = repo.odb().write(git2::OdbObjectType::Blob, &data)?;
            return Ok(Some(repo.find_blob(oid, None)?));
        }
    }
    Ok(None)
}
