        let kind = kind_of(delta.status());
        if kind == ChangeKind::Untracked || kind == ChangeKind::Ignored {
            continue;
        }
        let path = delta
            .new_file()
            .path()
            .map(|p| p.to_string_lossy().to_string())
            .or_else(|| delta.old_file().path().map(|p| p.to_string_lossy().to_string()))
            .unwrap_or_default();
        // resolve worktree/index content
        let counted = !seen.contains_key(&path);
        seen.insert(path.clone(), ());
        let (added, removed) = if counted {
            match workdir_counts(repo, &head_map, &path)? {
                Some((a, d)) if a != 0 || d != 0 => (Some(a), Some(d)),
                _ => (None, None),
            }
        } else {
            (None, None)
        };
        out.push(FileChange { path, kind, added, removed });
        if out.len() >= 50 {
            break;
        }
    }
    Ok(out)
}

/// Line counts between HEAD and the index/worktree for `path`.
fn workdir_counts(
    repo: &Repository,
    head_map: &HashMap<String, Oid>,
    path: &str,
) -> Result<Option<(u64, u64)>> {
    let head_blob = match head_map.get(path) {
        Some(oid) => Some(repo.find_blob(*oid, None)?),
        None => None,
    };
    // index version (staged) or worktree version
    let other = index_or_worktree_blob(repo, path)?;
    for b in [&head_blob, &other] {
        if let Some(b) = b {
            if let Ok(Some(content)) = b.content() {
                if content.contains(&0u8) {
                    return Ok(None);
                }
            }
        }
    }
    let patch = match (head_blob, other) {
        (Some(o), Some(n)) => Patch::from_blobs(
            Some(o),
            Some(std::path::Path::new(path)),
            Some(n),
            Some(std::path::Path::new(path)),
            None,
        )?,
        (Some(o), None) => Patch::from_blob_and_buffer(
            Some(o),
            Some(std::path::Path::new(path)),
            &[],
            Some(std::path::Path::new(path)),
            None,
        )?,
        (None, Some(n)) => Patch::from_blob_and_buffer(
            None,
            Some(std::path::Path::new(path)),
            Some(n),
            Some(std::path::Path::new(path)),
            None,
        )?,
        (None, None) => return Ok(None),
    };
    let (_ctx, add, del) = patch.line_stats()?;
    Ok(Some((add as u64, del as u64)))
}

/// Read the current content of `path`: from the index if staged, else the worktree.
fn index_or_worktree_blob(repo: &Repository, path: &str) -> Result<Option<git2::Blob>> {
    let index = repo.index()?;
    if let Some(entry) = index.get_path(std::path::Path::new(path), 0) {
        if let Ok(blob) = repo.find_blob(entry.id, None) {
            return Ok(Some(blob));
        }
    }
    if let Some(workdir) = repo.workdir() {
        let full = workdir.join(path);
        if let Ok(data) = std::fs::read(&full) {
            let oid = repo.odb().write(git2::OdbObjectType::Blob, &data)?;
            return Ok(Some(repo.find_blob(oid, None)?));
        }
    }
    Ok(None)
}
