use crate::git::{BranchRef, Commit, RepoData};
use std::collections::HashMap;

/// Colors used for graph lanes, cycled through as the graph gets deeper.
pub const GRAPH_COLORS: [u8; 10] = [12, 2, 5, 3, 1, 14, 10, 13, 11, 9];
/// Color used for the "uncommitted changes" pseudo node.
pub const DIRTY_COLOR: u8 = 8;

pub fn lane_color(lane: usize) -> u8 {
    if lane == 0 {
        GRAPH_COLORS[0]
    } else {
        GRAPH_COLORS[1 + (lane - 1) % (GRAPH_COLORS.len() - 1)]
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum RowKind {
    Commit(usize),
    Connector,
    Uncommitted,
}

/// One rendered row of the commit list.
#[derive(Debug, Clone)]
pub struct Row {
    pub kind: RowKind,
    /// lane -> commit index, snapshot taken just before this row
    pub before: Vec<usize>,
    /// lane -> commit index, snapshot taken just after this row
    pub after: Vec<usize>,
    /// lane of the marker for this row (commit / uncommitted node)
    pub marker_lane: Option<usize>,
    /// (source commit, target commit) connections drawn on this row
    pub links: Vec<(usize, usize)>,
    /// joins drawn on this row: (source lane, target lane) resolved at render time
    pub joins: Vec<(usize, usize)>,
    /// lane index of the uncommitted node when it is attached with a link
    pub dirty_lane: Option<usize>,
}

#[derive(Debug, Clone)]
pub struct Graph {
    pub rows: Vec<Row>,
    /// number of lanes (drives the prefix width)
    pub lanes: usize,
}

fn glyph(up: bool, down: bool, left: bool, right: bool) -> char {
    match (up, down, left, right) {
        (true, true, false, false) => '│',
        (false, false, true, true) => '─',
        (true, false, false, false) => '│',
        (false, true, false, false) => '│',
        (false, false, true, false) => '─',
        (true, true, false, true) => '├',
        (true, true, true, false) => '┤',
        (true, false, true, true) => '┼',
        (false, true, true, true) => '┬',
        (true, true, true, true) => '┼',
        (false, false, true, true) => '─',
        // corners
        (true, false, true, true) => '┼',
        _ => ' ',
    }
}

/// Build the graph rows for the repository snapshot.
pub fn build(data: &RepoData) -> Graph {
    let n = data.commits.len();
    let mut rows: Vec<Row> = Vec::new();
    let mut lanes: Vec<usize> = Vec::new(); // lane -> commit index
    let mut pending: Vec<(usize, usize)> = Vec::new(); // (source commit, target commit)
    let mut max_lanes = 0usize;

    for ci in 0..n {
        // Joins targeting this commit are drawn just above it.
        let here: Vec<usize> = pending.iter().filter(|p| p.1 == ci).map(|p| p.0).collect();
        if !here.is_empty() {
            let before = lanes.clone();
            let mut joins = Vec::new();
            for src in &here {
                if let (Some(sl), Some(tl)) = (lane_of(&lanes, *src), lane_of(&lanes, ci)) {
                    joins.push((sl, tl));
                }
            }
            // collapse the source lanes into the target lane
            let target = lane_of(&lanes, ci);
            let mut new_lanes: Vec<usize> = Vec::new();
            for (l, c) in lanes.iter().enumerate() {
                if Some(l) == target {
                    new_lanes.push(*c);
                } else if !here.contains(c) {
                    new_lanes.push(*c);
                }
            }
            let after = new_lanes.clone();
            rows.push(Row {
                kind: RowKind::Connector,
                before,
                after,
                marker_lane: None,
                links: Vec::new(),
                joins,
                dirty_lane: None,
            });
            lanes = new_lanes;
            max_lanes = max_lanes.max(lanes.len());
            pending.retain(|p| p.1 != ci);
        }

        let before = lanes.clone();
        let marker_lane = lane_of(&lanes, ci);
        let mut links: Vec<(usize, usize)> = Vec::new();

        // resolve parents
        let parents = data.commits[ci].parents.clone();
        for (pi, p) in parents.iter().enumerate() {
            let pidx = match data.commit_index(p) {
                Some(i) => i,
                None => continue,
            };
            match lane_of(&lanes, pidx) {
                Some(l) => {
                    if Some(l) != marker_lane {
                        pending.push((ci, pidx));
                    }
                }
                None => {
                    if pi == 0 && marker_lane.is_some() {
                        // first parent continues this lane
                        let l = marker_lane.unwrap();
                        lanes[l] = pidx;
                    } else {
                        // new lane for this parent
                        lanes.push(pidx);
                        let l = lanes.len() - 1;
                        if marker_lane.is_some() {
                            links.push((marker_lane.unwrap(), l));
                        }
                    }
                }
            }
        }
        let after = lanes.clone();
        rows.push(Row {
            kind: RowKind::Commit(ci),
            before,
            after,
            marker_lane,
            links,
            joins: Vec::new(),
            dirty_lane: None,
        });
        max_lanes = max_lanes.max(lanes.len());
    }

    // working tree changes are displayed as an extra node above HEAD
    let dirty_lane = if data.dirty.is_empty() {
        None
    } else {
        data.head_commit
            .and_then(|h| data.commit_index(&h))
            .map(|hi| attach_uncommitted(&mut rows, hi, &mut max_lanes))
    };

    Graph { rows, lanes: max_lanes, dirty_lane_placeholder: () }
}

fn lane_of(lanes: &[usize], commit: usize) -> Option<usize> {
    lanes.iter().position(|&c| c == commit)
}

fn attach_uncommitted(rows: &mut Vec<Row>, head_idx: usize, max_lanes: &mut usize) -> usize {
    // lane of HEAD at its row
    let head_row = rows.iter().position(|r| r.kind == RowKind::Commit(head_idx));
    let Some(hr) = head_row else { return 0 };
    let head_lane = match rows[hr].marker_lane {
        Some(l) => l,
        None => return 0,
    };
    // is that lane free on all rows between the new top row and HEAD's row?
    let free = (0..hr).all(|r| {
        let row = &rows[r];
        !lane_used(row, head_lane)
    });
    let lane = if free {
        head_lane
    } else {
        *max_lanes += 1;
        *max_lanes - 1
    };
    let mut new_rows: Vec<Row> = Vec::with_capacity(rows.len() + 1);
    new_rows.push(Row {
        kind: RowKind::Uncommitted,
        before: Vec::new(),
        after: Vec::new(),
        marker_lane: Some(lane),
        links: Vec::new(),
        joins: Vec::new(),
        dirty_lane: None,
    });
    for (i, row) in rows.iter_mut().enumerate() {
        if i + 1 < hr {
            // vertical line of the dirty node
            row.dirty_line_lane = Some(lane);
        }
        if i == hr && !free {
            row.links.push((head_lane, lane));
            row.dirty_lane = Some(lane);
        }
        new_rows.push(row.clone());
    }
    *rows = new_rows;
    lane
}
RSEOF
echo ok"}

