/// A row of the commit list together with the state of the graph columns.
#[derive(Debug, Clone)]
pub struct Row {
    pub kind: RowKind,
    /// lanes occupied just before this row (lane -> commit index)
    pub before: Vec<usize>,
    /// lanes occupied just after this row
    pub after: Vec<usize>,
    /// lane holding the marker of this row
    pub marker_lane: Option<usize>,
    /// horizontal connections drawn on this row: (from lane, to lane, color)
    pub links: Vec<(usize, usize, u8)>,
    /// joins drawn on this row: (source lane, target lane)
    pub joins: Vec<(usize, usize)>,
}

#[derive(Debug, Clone)]
pub struct Graph {
    pub rows: Vec<Row>,
    /// maximum number of lanes (drives the prefix width)
    pub lanes: usize,
    /// information about the "uncommitted changes" pseudo node
    pub dirty: Option<DirtyNode>,
}

#[derive(Debug, Clone)]
pub struct DirtyNode {
    pub lane: usize,
    /// row index of the HEAD commit row
    pub head_row: usize,
    /// true when the node is linked to HEAD from a separate lane
    pub linked: bool,
}

fn lane_of(lanes: &[usize], commit: usize) -> Option<usize> {
    lanes.iter().position(|&c| c == commit)
}

/// Build the row list and column layout for the given snapshot.
pub fn build(data: &RepoData) -> Graph {
    let n = data.commits.len();
    let mut rows: Vec<Row> = Vec::new();
    let mut lanes: Vec<usize> = Vec::new();
    let mut pending: Vec<(usize, usize)> = Vec::new();
    let mut max_lanes = 0usize;

    for ci in 0..n {
        // Joins pointing at this commit are rendered directly above it.
        let sources: Vec<usize> = pending
            .iter()
            .filter(|p| p.1 == ci)
            .map(|p| p.0)
            .collect();
        if !sources.is_empty() {
            let before = lanes.clone();
            let target_before = lane_of(&lanes, ci);
            let mut joins = Vec::new();
            for src in &sources {
                if let Some(sl) = lane_of(&lanes, *src) {
                    joins.push((sl, target_before.unwrap_or(sl)));
                }
            }
            // collapse the source lanes away, keeping the target
            let target = target_before;
            let mut new_lanes: Vec<usize> = Vec::new();
            for (l, c) in lanes.iter().enumerate() {
                if Some(l) == target {
                    new_lanes.push(*c);
                } else if !sources.contains(c) {
                    new_lanes.push(*c);
                }
            }
            let after = new_lanes.clone();
            rows.push(Row {
                kind: RowKind::Connector,
                before,
                after,
                marker_lane: None,
                links: Vec::new(),
                joins,
            });
            lanes = new_lanes;
            max_lanes = max_lanes.max(lanes.len());
            pending.retain(|p| p.1 != ci);
        }

        let before = lanes.clone();
        let marker_lane = lane_of(&lanes, ci);
        let mut links: Vec<(usize, usize, u8)> = Vec::new();

        let parents = data.commits[ci].parents.clone();
        for (pi, p) in parents.iter().enumerate() {
            let Some(pidx) = data.commit_index(p) else { continue };
            match lane_of(&lanes, pidx) {
                Some(l) => {
                    if Some(l) != marker_lane {
                        pending.push((ci, pidx));
                    }
                }
                None => {
                    if pi == 0 {
                        if let Some(l) = marker_lane {
                            lanes[l] = pidx;
                            continue;
                        }
                    }
                    lanes.push(pidx);
                    let l = lanes.len() - 1;
                    if let Some(ml) = marker_lane {
                        links.push((ml, l, crate::graph::lane_color(l)));
                    }
                }
            }
        }
        let after = lanes.clone();
        rows.push(Row {
            kind: RowKind::Commit(ci),
            before,
            after,
            marker_lane,
            links,
            joins: Vec::new(),
        });
        max_lanes = max_lanes.max(lanes.len());
    }

    // pending joins that never found their target (should not happen) are dropped

    // uncommitted changes pseudo node
    let dirty = if data.dirty.is_empty() {
        None
    } else {
        data.head_commit.and_then(|h| data.commit_index(&h)).and_then(|hi| {
            attach_dirty(&mut rows, hi, &mut max_lanes)
        })
    };

    Graph { rows, lanes: max_lanes, dirty }
}

fn attach_dirty(rows: &mut Vec<Row>, head_idx: usize, max_lanes: &mut usize) -> Option<DirtyNode> {
    let hr = rows.iter().position(|r| r.kind == RowKind::Commit(head_idx))?;
    let head_lane = rows[hr].marker_lane?;
    let free = (0..hr).all(|r| !lane_used(&rows[r], head_lane));
    let lane = if free {
        head_lane
    } else {
        *max_lanes += 1;
        *max_lanes - 1
    };
    let mut out: Vec<Row> = Vec::with_capacity(rows.len() + 1);
    out.push(Row {
        kind: RowKind::Uncommitted,
        before: Vec::new(),
        after: Vec::new(),
        marker_lane: Some(lane),
        links: Vec::new(),
        joins: Vec::new(),
    });
    for (i, row) in rows.iter_mut().enumerate() {
        if i + 1 < hr {
            // the vertical line of the dirty node passes through this row
            row.after.push(usize::MAX - 1);
            row.before.push(usize::MAX - 1);
        }
        if i == hr && !free {
            row.links.push((head_lane, lane, DIRTY_COLOR));
        }
        out.push(row.clone());
    }
    *rows = out;
    Some(DirtyNode { lane, head_row: hr + 1, linked: !free })
}

/// Does any glyph occupy `lane` in this row?
fn lane_used(row: &Row, lane: usize) -> bool {
    if row.before.get(lane).is_some() || row.after.get(lane).is_some() {
        return true;
    }
    for (a, b, _) in &row.links {
        if lane >= *a.min(b) && lane <= *a.max(b) {
            return true;
        }
    }
    false
}

/// Compute the glyph for a cell from the four directions.
pub fn cell_glyph(up: bool, down: bool, left: bool, right: bool) -> char {
    match (up, down, left, right) {
        (true, true, false, false) => '│',
        (false, false, true, true) => '─',
        (true, false, false, false) => '│',
        (false, true, false, false) => '│',
        (false, false, true, false) => '─',
        (true, true, false, true) => '├',
        (true, true, true, false) => '┤',
        (true, false, true, true) => '┼',
        (false, true, true, true) => '┬',
        (true, true, true, true) => '┼',
        (true, false, true, false) => '┘',
        (false, true, true, false) => '┐',
        _ => ' ',
    }
}

/// Rounded corner glyphs used at the ends of horizontal runs.
pub fn corner_glyph(up: bool, down: bool, left: bool, right: bool) -> Option<char> {
    match (up, down, left, right) {
        (true, false, true, false) => Some('╯'),
        (false, true, true, false) => Some('╮'),
        (true, false, false, true) => Some('╰'),
        (false, true, false, true) => Some('╭'),
        _ => None,
    }
}
