pub fn border_style() -> Style {
    Style::default().fg(BORDER_COLOR)
}

fn span(text: &str, style: Style) -> Span<'static> {
    Span::styled(text.to_string(), style)
}

/// Build the graph prefix spans for a row.
pub fn prefix_spans(
    row: &Row,
    lanes: usize,
    dirty: Option<&DirtyNode>,
    row_index: usize,
) -> Vec<Span<'static>> {
    let mut out: Vec<Span<'static>> = Vec::new();
    out.push(Span::raw(" "));
    // horizontal runs: (left lane cell index, right lane cell index, color)
    let mut runs: Vec<(usize, usize, u8)> = Vec::new();
    for (a, b, c) in &row.links {
        runs.push((*a, *b, *c));
    }
    for (s, t) in &row.joins {
        runs.push((*s, *t, lane_color(*s)));
    }
    let bold = Style::default().add_modifier(Modifier::BOLD);
    let bold_fg = |c: u8| Style::default().add_modifier(Modifier::BOLD).fg(Color::Indexed(c));

    // dirty node occupies its lane across rows 0..=head_row
    let dirty_lane = dirty.map(|d| d.lane);
    let dirty_up = dirty
        .map(|d| row_index > 0 && row_index <= d.head_row)
        .unwrap_or(false);
    let dirty_down = dirty
        .map(|d| row_index < d.head_row)
        .unwrap_or(false);

    for l in 0..lanes {
        // lane cell
        let up = row.before.get(l).is_some() || (dirty_lane == Some(l) && dirty_up);
        let down = row.after.get(l).is_some() || (dirty_lane == Some(l) && dirty_down);
        let mut left = false;
        let mut right = false;
        let mut run_color: Option<u8> = None;
        for (a, b, c) in &runs {
            let (lo, hi) = (*a).min(*b).max((*b).min(*a));
            let (lo, hi) = ((*a).min(*b), (*a).max(*b));
            if l > *lo && l < *hi {
                left = true;
                right = true;
                run_color = Some(*c);
            } else if l == *hi {
                if *a > *b {
                    left = true;
                } else {
                    right = true;
                }
                run_color = Some(*c);
            }
            let _ = (lo, hi);
        }
        let cell = match row.marker_lane {
            Some(ml) if ml == l => {
                if let Some(dl) = dirty_lane {
                    if dl == l && row.kind == RowKind::Uncommitted {
                        '●'
                    } else {
                        '◉'
                    }
                } else {
                    '●'
                }
            }
            _ => {
                if up || down || left || right {
                    let g = match (up, down, left, right) {
                        (true, false, true, false) => '╯',
                        (false, true, true, false) => '╮',
                        (true, false, false, true) => '╰',
                        (false, true, false, true) => '╭',
                        (u, d, l, r) => cell_glyph(u, d, l, r),
                    };
                    g
                } else {
                    ' '
                }
            }
        };
        let color = if cell == ' ' && run_color.is_none() {
            None
        } else if let Some(rc) = run_color {
            if row.marker_lane == Some(l) {
                Some(lane_color(l))
            } else if cell == '─' {
                Some(rc)
            } else if up || down {
                Some(lane_color(l))
            } else {
                Some(rc)
            }
        } else if cell != ' ' {
            Some(lane_color(l))
        } else {
            None
        };
        let st = match color {
            Some(c) => bold_fg(c),
            None => bold,
        };
        out.push(span(&cell.to_string(), st));
        // connector between lane l and l+1
        if l + 1 < lanes {
            let mut has = false;
            let mut rc = None;
            for (a, b, c) in &runs {
                let (lo, hi) = ((*a).min(*b), (*a).max(*b));
                if l >= *lo && l + 1 <= *hi && *hi > *lo {
                    has = true;
                    rc = Some(*c);
                }
            }
            let st = match rc {
                Some(c) => bold_fg(c),
                None => bold,
            };
            let ch = if has { '─' } else { ' ' };
            out.push(span(&ch.to_string(), st));
        }
    }
    out.push(span(" ", bold));
    out
}
RSEOF
echo ok"}

