/// Spans for the right-hand side (date / author / hash) of a commit row.
fn right_spans(data: &RepoData, idx: usize, avail: usize) -> Vec<Span<'static>> {
    let c = &data.commits[idx];
    let mut spans: Vec<Span<'static>> = Vec::new();
    let mut fields: Vec<Span<'static>> = Vec::new();
    let date = format_date(c.time);
    let author: String = c.author.chars().take(AUTHOR_W).collect();
    let author = format!("{:<width$}", author, width = AUTHOR_W);
    let hash = c.short.clone();
    // decide which fields fit
    let date_w = date.chars().count();
    let author_w = author.chars().count();
    let hash_w = hash.chars().count();
    let mut used = 0usize;
    let mut show_date = false;
    let mut show_author = false;
    let mut show_hash = false;
    if avail >= date_w + 2 + author_w + 2 + hash_w + 1 {
        show_date = true; show_author = true; show_hash = true;
        used = date_w + 2 + author_w + 2 + hash_w + 1;
    } else if avail >= date_w + 2 + author_w + 1 {
        show_date = true; show_author = true;
        used = date_w + 2 + author_w + 1;
    } else if avail >= author_w + 2 {
        show_author = true;
        used = author_w + 2;
    }
    if show_hash {
        fields.push(span(&hash, Style::default().fg(HASH_C)));
        fields.push(Span::raw(" "));
        fields.push(Span::raw(" "));
    }
    if show_author {
        fields.push(span(&author, Style::default().fg(AUTHOR_C)));
        fields.push(Span::raw(" "));
        if show_date {
            fields.push(Span::raw(" "));
        }
    }
    if show_date {
        fields.push(span(&date, Style::default().fg(DATE_C)));
    }
    // assemble right aligned: pad + fields
    if used > 0 {
        let pad = avail.saturating_sub(used);
        if pad > 0 {
            spans.push(Span::raw(" ".repeat(pad)));
        }
        spans.extend(fields);
    }
    spans
}

pub fn format_date(secs: i64) -> String {
    let (y, mo, d) = civil_from_days(secs.div_euclid(86400));
    let rem = secs.rem_euclid(86400);
    let h = rem / 3600;
    let mi = (rem % 3600) / 60;
    let s = rem % 60;
    format!("{:04}-{:02}-{:02}", y, mo, d)
}

pub fn format_datetime(secs: i64) -> String {
    let (y, mo, d) = civil_from_days(secs.div_euclid(86400));
    let rem = secs.rem_euclid(86400);
    let h = rem / 3600;
    let mi = (rem % 3600) / 60;
    let s = rem % 60;
    format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", y, mo, d, h, mi, s)
}

/// days since epoch -> (year, month, day), proleptic Gregorian
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}
