use crate::app::{App, Mode, RightLabel};
use crate::git::{ChangeKind, RepoData};
use crate::graph::{lane_color, DirtyNode, Row, RowKind, DIRTY_COLOR};
use ratatui::layout::{Alignment, Constraint, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, Paragraph, Wrap};

pub const BORDER: Color = Color::DarkGray;
const DATE_C: Color = Color::DarkGray;
const AUTHOR_C: Color = Color::Cyan;
const HASH_C: Color = Color::Yellow;
const SELECT_BG: Color = Color::DarkGray;
const ADDED_C: Color = Color::Green;
const DELETED_C: Color = Color::Red;
const MODIFIED_C: Color = Color::Yellow;
const SEARCH_BORDER: Color = Color::Cyan;
const POPUP_BG: Color = Color::Indexed(0);
const BRANCHES_BORDER: Color = Color::Blue;

pub fn fg(c: u8) -> Style {
    Style::default().fg(Color::Indexed(c))
}
pub fn bold_fg(c: u8) -> Style {
    Style::default().add_modifier(Modifier::BOLD).fg(Color::Indexed(c))
}
pub fn bold() -> Style {
    Style::default().add_modifier(Modifier::BOLD)
}

pub fn layout(area: Rect) -> (Rect, Rect, Rect) {
    let bottom_h = area.height * 3 / 10;
    let chunks = Layout::vertical([
        Constraint::Fill(1),
        Constraint::Length(bottom_h),
        Constraint::Length(1),
    ])
    .split(area);
    (chunks[0], chunks[1], chunks[2])
}

pub fn bottom_layout(area: Rect) -> (Rect, Rect) {
    if area.height >= 3 && area.width >= 57 {
        let w = area.width / 2;
        let l = Layout::horizontal([Constraint::Length(w), Constraint::Fill(1)]).split(area);
        (l[0], l[1])
    } else {
        let detail = if area.height == 0 {
            0
        } else {
            area.height.min(2.max((area.height + 1) / 2))
        };
        let l = Layout::vertical([Constraint::Length(detail), Constraint::Fill(1)]).split(area);
        (l[0], l[1])
    }
}

struct Run {
    lo: usize,
    hi: usize,
    color: u8,
    skip_marker: bool,
}

fn prefix_cells(
    row: &Row,
    lanes: usize,
    dirty: Option<&DirtyNode>,
    row_index: usize,
) -> Vec<(char, Option<u8>)> {
    let mut runs: Vec<Run> = Vec::new();
    for (a, b, c) in &row.links {
        runs.push(Run { lo: (*a).min(*b), hi: (*a).max(*b), color: *c, skip_marker: true });
    }
    for (s, t) in &row.joins {
        let far = (*s).max(*t);
        runs.push(Run { lo: (*s).min(*t), hi: far, color: lane_color(far), skip_marker: false });
    }

    let dirty_up = dirty
        .map(|d| row_index > 0 && row_index <= d.head_row)
        .unwrap_or(false);
    let dirty_down = dirty.map(|d| row_index < d.head_row).unwrap_or(false);
    let dirty_lane = dirty.map(|d| d.lane);

    let mut cells: Vec<(char, Option<u8>)> = Vec::new();
    cells.push((' ', None));
    for l in 0..lanes {
        let up = row.before.get(l).is_some() || (dirty_lane == Some(l) && dirty_up);
        let down = row.after.get(l).is_some() || (dirty_lane == Some(l) && dirty_down);
        let mut left = false;
        let mut right = false;
        for r in &runs {
            if l > r.lo && l < r.hi {
                left = true;
                right = true;
            } else if l == r.lo && r.lo < r.hi && !r.skip_marker {
                right = true;
            } else if l == r.hi && r.lo < r.hi {
                left = true;
            }
        }
        let (cell, color) = if row.marker_lane == Some(l) {
            match row.kind {
                RowKind::Uncommitted => ('●', Some(DIRTY_COLOR)),
                _ => ('◉', Some(lane_color(l))),
            }
        } else if up || down || left || right {
            let g = match (up, down, left, right) {
                (true, false, true, false) => '╯',
                (false, true, true, false) => '╮',
                (true, false, false, true) => '╰',
                (false, true, false, true) => '╭',
                (true, true, false, true) => '├',
                (true, true, true, false) => '┤',
                (true, false, true, true) => '┼',
                (false, true, true, true) => '┬',
                (true, true, true, true) => '┼',
                (true, true, false, false) => '│',
                (false, false, true, true) => '─',
                (true, false, false, false) => '│',
                (false, true, false, false) => '│',
                (false, false, true, false) => '─',
                (false, false, false, true) => '─',
                _ => ' ',
            };
            let color = if up || down {
                if dirty_lane == Some(l) {
                    DIRTY_COLOR
                } else {
                    lane_color(l)
                }
            } else {
                runs
                    .iter()
                    .find(|r| l >= r.lo && l <= r.hi)
                    .map(|r| r.color)
                    .unwrap_or(0)
            };
            (g, Some(color))
        } else {
            (' ', None)
        };
        cells.push((cell, color));
        let mut has = false;
        let mut color = None;
        for r in &runs {
            if l >= r.lo && l < r.hi {
                has = true;
                color = Some(r.color);
            }
        }
        cells.push((if has { '─' } else { ' ' }, color));
    }
    cells.push((' ', None));
    cells
}

pub fn format_date(secs: i64) -> String {
    let (y, mo, d) = civil_from_days(secs.div_euclid(86400));
    format!("{:04}-{:02}-{:02}", y, mo, d)
}

pub fn format_datetime(secs: i64) -> String {
    let (y, mo, d) = civil_from_days(secs.div_euclid(86400));
    let rem = secs.rem_euclid(86400);
    format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", y, mo, d, rem / 3600, (rem % 3600) / 60, rem % 60)
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

/// Build the spans of one list row.
fn row_spans(row: &Row, row_index: usize, app: &App, width: u16) -> Vec<Span<'static>> {
    let data = &app.data;
    let lanes = app.graph.lanes;
    let prefix_w = 2 * lanes + 2;
    let inner = (width as usize).saturating_sub(2);
    let avail = inner.saturating_sub(prefix_w);
    let right_w = if avail >= 81 {
        30
    } else if avail >= 72 {
        21
    } else if avail >= 61 {
        9
    } else {
        0
    };

    let mut spans: Vec<Span<'static>> = Vec::new();
    let cells = prefix_cells(row, lanes, app.graph.dirty.as_ref(), row_index);
    for (i, (ch, color)) in cells.iter().enumerate() {
        let st = match color {
            Some(c) => bold_fg(*c),
            None => {
                if i == 0 {
                    Style::default()
                } else {
                    bold()
                }
            }
        };
        spans.push(Span::styled(ch.to_string(), st));
    }

    match row.kind {
        RowKind::Commit(ci) => {
            let c = &data.commits[ci];
            let label = app.branch_label(ci);
            let label_w = label.as_ref().map(|l| crate::app::display_width(&l.0) + 1).unwrap_or(0);
            let msg_w = avail.saturating_sub(label_w + right_w);
            if let Some((text, item)) = label {
                let st = if app.selected == row_index {
                    fg(0)
                } else {
                    bold_fg(lane_color(row.marker_lane.unwrap_or(0)))
                };
                spans.push(Span::styled(format!("[{}]", text), st));
                spans.push(Span::raw(" "));
            }
            let msg: String = crate::app::truncate(&c.summary, msg_w);
            let mw = crate::app::display_width(&msg);
            spans.push(Span::raw(msg));
            if right_w > 0 {
                let pad = msg_w.saturating_sub(mw);
                if pad > 0 {
                    spans.push(Span::raw(" ".repeat(pad)));
                }
                let date = format_date(c.time);
                let author: String = crate::app::truncate(&c.author, AUTHOR_W);
                let author = format!("{:<width$}", author, width = AUTHOR_W);
                match right_w {
                    30 => {
                        spans.push(Span::styled(date, Style::default().fg(DATE_C)));
                        spans.push(Span::raw("  "));
                        spans.push(Span::styled(author, Style::default().fg(AUTHOR_C)));
                        spans.push(Span::raw("  "));
                        spans.push(Span::styled(c.short.clone(), Style::default().fg(HASH_C)));
                        spans.push(Span::raw(" "));
                    }
                    21 => {
                        spans.push(Span::styled(date, Style::default().fg(DATE_C)));
                        spans.push(Span::raw("  "));
                        spans.push(Span::styled(author, Style::default().fg(AUTHOR_C)));
                        spans.push(Span::raw(" "));
                    }
                    9 => {
                        spans.push(Span::styled(author, Style::default().fg(AUTHOR_C)));
                        spans.push(Span::raw(" "));
                    }
                    _ => {}
                }
            }
        }
        RowKind::Uncommitted => {
            let msg = format!("uncommitted changes ({})", data.dirty.len());
            spans.push(Span::styled(msg, fg(15)));
        }
        RowKind::Connector => {}
    }
    spans
}

pub fn render_list(f: &mut ratatui::Frame, area: Rect, app: &App) {
    let block = Block::bordered().title(" Commits ").border_style(Style::default().fg(BORDER));
    let inner = block.inner(area);
    f.render_widget(block, area);
    let visible = inner.height as usize;
    if visible == 0 {
        return;
    }
    let total = app.graph.rows.len();
    let offset = if total > visible {
        app.selected.saturating_sub(visible - 1).min(total - visible)
    } else {
        0
    };
    for i in 0..visible {
        let idx = offset + i;
        if idx >= total {
            break;
        }
        let row = &app.graph.rows[idx];
        let spans = row_spans(row, idx, app, area.width);
        let selected = app.selected == idx;
        let base = if selected {
            Style::default().add_modifier(Modifier::BOLD).bg(SELECT_BG)
        } else {
            Style::default()
        };
        let line = Line::from(spans).style(base);
        let rect = Rect { x: inner.x, y: inner.y + i as u16, width: inner.width, height: 1 };
        f.render_widget(line, rect);
    }
}
