pub fn render_detail(f: &mut ratatui::Frame, area: Rect, app: &App) {
    let block = Block::bordered().title(" Commit Detail ").border_style(Style::default().fg(BORDER));
    let inner = block.inner(area);
    f.render_widget(block, area);
    if inner.height == 0 || inner.width == 0 {
        return;
    }
    let lines: Vec<Line<'static>> = match app.selected_row().map(|r| r.kind) {
        Some(RowKind::Commit(ci)) => {
            let c = &app.data.commits[ci];
            let mut v: Vec<Line<'static>> = Vec::new();
            v.push(Line::from(vec![
                Span::styled("Commit: ", bold()),
                Span::styled(c.id.to_string(), fg(3)),
            ]));
            v.push(Line::from(vec![
                Span::styled("Author: ", bold()),
                Span::styled(format!("{} <{}>", c.author, c.email), fg(4)),
            ]));
            v.push(Line::from(vec![
                Span::styled("Date:   ", bold()),
                Span::styled(crate::ui::format_datetime(c.time), fg(8)),
            ]));
            if !c.parents.is_empty() {
                let names: Vec<String> = c.parents.iter().map(crate::git::short_of).collect();
                v.push(Line::from(vec![
                    Span::styled("Parent: ", bold()),
                    Span::styled(names.join(", "), fg(8)),
                ]));
            }
            v.push(Line::from(""));
            v.push(Line::from(c.body.clone()));
