cd /workspace && cat >> src/ui.rs <<'RSEOF'

fn key_chip(key: &str) -> Span<'static> {
    Span::styled(
        format!(" {} ", key),
        Style::default().add_modifier(Modifier::BOLD).fg(Color::Black).bg(Color::Cyan),
    )
}
fn desc_span(desc: &str) -> Span<'static> {
    Span::styled(desc.to_string(), Style::default().fg(Color::White))
}

pub fn render_status(f: &mut ratatui::Frame, area: Rect, app: &App) {
    let mut spans: Vec<Span<'static>> = Vec::new();
    spans.push(Span::styled(
        " repo ",
        Style::default().add_modifier(Modifier::BOLD).fg(Color::Black).bg(Color::Magenta),
    ));
    spans.push(Span::raw(" "));
    let branch = app.data.head_branch.clone().unwrap_or_else(|| "HEAD".to_string());
    spans.push(Span::styled(
        format!(" {} ", branch),
        Style::default().fg(Color::Black).bg(Color::Green),
    ));
    spans.push(Span::raw(" "));

    let mut right: Option<&'static str> = None;
    match &app.mode {
        Mode::Normal => {
            let hints: [(&str, &str); 6] = [
                ("j/k", "move"),
                ("Enter", "checkout"),
                ("b", "branch"),
                ("f", "fetch"),
                ("?", "help"),
                ("q", "quit"),
            ];
            push_hints(&mut spans, &hints);
        }
        Mode::Help => {
            push_hints(&mut spans, &[("Esc/q", "close help")]);
            right = Some("HELP");
        }
        Mode::Error(_) => {
            let msg = app.mode_error().unwrap_or_default();
            spans.push(Span::styled(
                format!(" {} ", msg),
                Style::default().add_modifier(Modifier::BOLD).fg(Color::White).bg(Color::Red),
            ));
            spans.push(Span::raw(" "));
            push_hints(&mut spans, &[("Esc/Enter", "close")]);
            right = Some("ERROR");
        }
        Mode::Confirm => {
            push_hints(&mut spans, &[("y", "yes"), ("n", "no")]);
            right = Some("CONFIRM");
        }
        Mode::Input => {
            push_hints(&mut spans, &[("Enter", "confirm"), ("Esc", "cancel")]);
            right = Some("INPUT");
        }
    }

    if let Some(label) = right {
        let left_w: usize = spans.iter().map(|s| crate::app::display_width(&s.content)).sum();
        let label_w = label.chars().count() + 1;
        let total = area.width as usize;
        if left_w + label_w <= total {
            let pad = total - left_w - label_w;
            if pad > 0 {
                spans.push(Span::raw(" ".repeat(pad)));
            }
            spans.push(Span::styled(
                format!(" {}", label),
                Style::default().add_modifier(Modifier::BOLD).fg(Color::Black).bg(Color::Yellow),
            ));
        }
    }
    let line = Line::from(spans);
    f.render_widget(line, area);
}

fn push_hints(spans: &mut Vec<Span<'static>>, hints: &[(&str, &str)]) {
    let last = hints.len() - 1;
    for (i, (k, d)) in hints.iter().enumerate() {
        spans.push(key_chip(k));
        if i == last {
            spans.push(desc_span(d));
        } else {
            spans.push(desc_span(&format!("{} ", d)));
        }
    }
}
RSEOF
