/// Rect for the bottom-anchored search popup.
pub fn search_rect(area: Rect, content_h: usize) -> Rect {
    let cols = Layout::horizontal([
        Constraint::Percentage(20),
        Constraint::Percentage(60),
        Constraint::Percentage(20),
    ])
    .split(area);
    let w = cols[1].width;
    let x = cols[1].x;
    let h = content_h.min(12).min(area.height.saturating_sub(2) as usize).max(0) as u16;
    let y = area.height.saturating_sub(1).saturating_sub(h);
    Rect { x, y, width: w, height: h }
}

/// Rect for the centred help popup.
pub fn help_rect(area: Rect) -> Rect {
    let v = Layout::vertical([
        Constraint::Percentage(15),
        Constraint::Percentage(70),
        Constraint::Percentage(15),
    ])
    .split(area);
    let h = Layout::horizontal([
        Constraint::Percentage(20),
        Constraint::Percentage(60),
        Constraint::Percentage(20),
    ])
    .split(v[1]);
    h[1]
}

/// Rect for the centred "New Branch Name" popup.
pub fn input_rect(area: Rect) -> Rect {
    let w = area.width / 2;
    let h = (area.height * 20 / 100).max(2);
    let x = (area.width.saturating_sub(w) + 1) / 2;
    let y = area.height.saturating_sub(h) / 2;
    Rect { x, y, width: w, height: h }
}

pub const HELP_TEXT: &str = "Navigation\n  j / \u{2193}      Move down\n  k / \u{2191}      Move up\n  ] / Tab    Select next branch\n  [ / S-Tab  Select previous branch\n  h / \u{2190}      Select left branch (same commit)\n  l / \u{2192}      Select right branch (same commit)\n  Ctrl+d     Page down\n  Ctrl+u     Page up\n  g / Home   Go to top\n  G / End    Go to bottom\n  @          Jump to HEAD (current branch)\n\nGit Operations\n  Enter      Checkout selected branch/commit\n  b          Create new branch\n  d          Delete branch\n  f          Fetch from origin\n\nSearch\n  /          Search branches\n  \u{2191} / C-k    Select previous result\n  \u{2193} / C-j    Select next result\n  Enter      Jump to selected branch\n  Esc        Cancel search\n\nOther\n  R          Refresh\n  ?          Toggle this help\n  q / Esc    Quit";

pub fn render_help(f: &mut ratatui::Frame, area: Rect) {
    let block = Block::bordered()
        .title(" Help ")
        .border_style(Style::default().fg(SEARCH_BORDER))
        .title_style(Style::default().fg(SEARCH_BORDER))
        .style(Style::default().bg(POPUP_BG));
    let inner = block.inner(area);
    f.render_widget(block, area);
    let lines: Vec<Line<'static>> = HELP_TEXT
        .lines()
        .map(|l| {
            if l.starts_with("  ") {
                Line::from(Span::raw(l.to_string()))
            } else if l.is_empty() {
                Line::from("")
            } else {
                Line::from(Span::styled(l.to_string(), bold()))
            }
        })
        .collect();
    let par = Paragraph::new(lines);
    f.render_widget(par, inner);
}

pub fn render_input_popup(f: &mut ratatui::Frame, area: Rect, title: &str, query: &str) {
    let block = Block::bordered()
        .title(format!(" {} ", title))
        .border_style(Style::default().fg(SEARCH_BORDER))
        .title_style(Style::default().fg(SEARCH_BORDER))
        .style(Style::default().bg(POPUP_BG));
    let inner = block.inner(area);
    f.render_widget(block, area);
    if inner.height == 0 {
        return;
    }
    let mut lines: Vec<Line<'static>> = Vec::new();
    lines.push(Line::from(""));
    let mut spans = vec![Span::raw("  ")];
    if !query.is_empty() {
        spans.push(Span::styled(
            query.to_string(),
            Style::default().fg(Color::White).add_modifier(Modifier::UNDERLINED),
        ));
    }
    spans.push(Span::styled("_", fg(6)));
    lines.push(Line::from(spans));
    let par = Paragraph::new(lines);
    f.render_widget(par, inner);
}
