pub fn render_search(f: &mut ratatui::Frame, rect: Rect, app: &App) {
    let block = Block::bordered()
        .title(" Search branches ")
        .border_style(Style::default().fg(SEARCH_BORDER))
        .title_style(Style::default().fg(SEARCH_BORDER))
