        lines.push(Line::from(Span::styled("\u{2500}".repeat(w), fg(8))));
        let interior = inner.height as usize;
        let area = if interior >= 10 { interior - 3 } else { interior.saturating_sub(2) };
        let area = area.max(1);
        let start = app.search_selected.saturating_sub(area - 1).min(results.len() - 1);
        for i in 0..area.min(results.len()) {
            let idx = start + i;
            let item = &results[idx];
            let sel = idx == app.search_selected;
            let marker = if sel {
                if i + 1 == area.min(results.len()) && start + area < results.len() {
                    '\u{25BC}'
                } else {
                    '\u{25B6}'
                }
            } else if i == 0 && start > 0 {
                '\u{2191}'
            } else if i + 1 == area.min(results.len()) && start + area < results.len() {
                '\u{2193}'
            } else {
                ' '
            };
            let mstyle = if sel { fg(6) } else { fg(8) };
            let mut spans = vec![Span::styled(marker.to_string(), mstyle), Span::raw(" ")];
            let name = &item.0;
            let matched = &item.2;
            for (i, ch) in name.chars().enumerate() {
                let st = if sel {
                    Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)
                } else if matched.contains(&i) {
                    bold_fg(3)
                } else {
                    fg(15)
                };
                spans.push(Span::styled(ch.to_string(), st));
            }
            lines.push(Line::from(spans));
        }
        lines.push(Line::from(Span::styled(
            "  \u{2191}\u{2193}: select  Enter: jump  Esc: cancel",
            fg(8),
        )));
    }
    let par = Paragraph::new(lines);
    f.render_widget(par, inner);
}

