use crate::config::Config;
use crate::git::{self, FileChange, RepoData};
use crate::graph::{self, Graph, Row, RowKind};
use ratatui::backend::CrosstermBackend;
use ratatui::crossterm::event::{self, Event, KeyCode, KeyEvent, KeyModifiers};
use ratatui::crossterm::terminal::{
    disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen,
};
use ratatui::Terminal;
use std::io::stdout;
use std::time::{Duration, Instant};

pub enum Mode {
    Normal,
    Help,
    Error(String),
    Confirm,
    Input,
}

pub enum InputKind {
    BranchName,
    Search,
}

#[derive(Debug, Clone, PartialEq)]
pub enum RightLabel {
    None,
    Help,
    Error,
    Confirm,
    Input,
}

/// (display name, item index, matched character positions)
pub type SearchItem = (String, usize, Vec<usize>);

pub struct App {
    pub data: RepoData,
    pub graph: Graph,
    pub commit_files: Vec<Vec<FileChange>>,
    pub selected: usize,
    pub branch_sel: usize,
    pub mode: Mode,
    pub input_kind: InputKind,
    pub input: String,
    pub search_selected: usize,
    pub error: Option<String>,
    pub confirm_action: Option<usize>,
    pub config: Config,
    pub last_refresh: Instant,
    pub last_fetch: Instant,
    pub quit: bool,
}

impl App {
    pub fn selected_row(&self) -> Option<&Row> {
        self.graph.rows.get(self.selected)
    }

    pub fn mode_error(&self) -> Option<&str> {
        match &self.mode {
            Mode::Error(m) => Some(m),
            _ => None,
        }
    }

    /// Branch items of the commit of the given row: (name, is_head)
    pub fn branch_items(&self, ci: usize) -> Vec<(String, usize)> {
        let Some(c) = self.data.commits.get(ci) else { return Vec::new() };
        let tip = c.id;
        let mut items: Vec<(String, usize)> = Vec::new();
        for b in &self.data.branches {
            if b.tip == tip {
                let name = if b.is_remote() && !self.data.branches.iter().any(|o| {
                    !o.is_remote() && o.local_name == b.local_name && o.tip == tip
                }) {
                    b.name.clone()
                } else {
                    b.local_name.clone()
                };
                items.push((name, if b.is_remote() { 1 } else { 0 }));
            }
        }
        items.sort_by(|a, b| a.0.cmp(&b.0));
        items.dedup_by(|a, b| a.0 == b.0);
        items
    }

    /// (label text, color index) for a commit row.
    pub fn branch_label(&self, ci: usize) -> Option<(String, usize)> {
        let items = self.branch_items(ci);
        if items.is_empty() {
            return None;
        }
        let idx = self.branch_sel.min(items.len() - 1);
        let (name, _) = items[idx].clone();
        let color = crate::graph::lane_color(self.graph.rows[self.selected].marker_lane.unwrap_or(0));
        let text = if items.len() == 1 {
            name
        } else if items.len() == 2 && items[0].1 == 0 && items[1].1 == 1 {
            format!("{} \u{2194} {}", items[0].0, short_remote(&items[1].0))
        } else {
            format!("{} +{}", name, items.len() - 1)
        };
        Some((text, color))
    }

    pub fn search_results(&self) -> Vec<SearchItem> {
        let q = self.input.to_lowercase();
        let mut out: Vec<SearchItem> = Vec::new();
        for (i, ci) in self.graph.rows.iter().enumerate() {
            if let RowKind::Commit(c) = ci.kind {
                let items = self.branch_items(c);
                let idx = self.branch_sel.min(items.len().saturating_sub(1));
                let _ = idx;
                for (bi, (name, _)) in items.iter().enumerate() {
                    if let Some(pos) = fuzzy_match(name, &q) {
                        out.push((name.clone(), bi, pos));
                    }
                }
            }
        }
        let _ = i_unused();
        out
    }
}

fn i_unused() -> usize {
    0
}

fn short_remote(name: &str) -> String {
    name.split('/').next().unwrap_or(name).to_string()
}

/// Greedy subsequence match, returns matched indices; prefix matches are preferred.
fn fuzzy_match(name: &str, q: &str) -> Option<Vec<usize>> {
    if q.is_empty() {
        return None;
    }
    let lower = name.to_lowercase();
    let chars: Vec<char> = lower.chars().collect();
    let qchars: Vec<char> = q.chars().collect();
    let mut idx = 0usize;
    let mut matched = Vec::new();
    for qc in &qchars {
        let mut found = None;
        while idx < chars.len() {
            if chars[idx] == *qc {
                found = Some(idx);
                idx += 1;
                break;
            }
            idx += 1;
        }
        let f = found?;
        matched.push(f);
    }
    Some(matched)
}

pub fn display_width(s: &str) -> usize {
    unicode_width::UnicodeWidthStr::width(s)
}

pub fn truncate(s: &str, w: usize) -> String {
    if w == 0 {
        return String::new();
    }
    let mut out = String::new();
    let mut width = 0usize;
    for ch in s.chars() {
        let cw = unicode_width::UnicodeWidthChar::width(ch).unwrap_or(0);
        if width + cw > w {
            break;
        }
        out.push(ch);
        width += cw;
    }
    out
}
