impl App {
    fn handle_key(&mut self, key: KeyEvent) {
        match &self.mode {
            Mode::Help => match key.code {
                KeyCode::Char('q') | KeyCode::Esc => self.mode = Mode::Normal,
                _ => {}
            },
            Mode::Error(_) => match key.code {
                KeyCode::Esc | KeyCode::Enter => self.mode = Mode::Normal,
                _ => {}
            },
            Mode::Confirm => match key.code {
                KeyCode::Char('y') => {
                    if let Some(ci) = self.confirm_action.take() {
                        self.delete_branch(ci);
                    }
                    self.mode = Mode::Normal;
                    self.refresh();
                }
                KeyCode::Char('n') | KeyCode::Esc | KeyCode::Enter => {
                    self.confirm_action = None;
                    self.mode = Mode::Normal;
                }
                KeyCode::Char('q') => self.quit = true,
                _ => {}
            },
            Mode::Input => match self.input_kind {
                InputKind::BranchName => match key.code {
                    KeyCode::Enter => {
                        let name = self.input.clone();
                        if !name.is_empty() {
                            self.create_branch(name);
                            self.mode = Mode::Normal;
                            self.input.clear();
                            self.refresh();
                        }
                    }
                    KeyCode::Esc => {
                        self.mode = Mode::Normal;
                        self.input.clear();
                    }
                    KeyCode::Backspace => {
                        self.input.pop();
                    }
                    KeyCode::Char(c) => self.input.push(c),
                    _ => {}
                },
                InputKind::Search => match key.code {
                    KeyCode::Enter => {
                        if let Some(item) = self.search_results().get(self.search_selected) {
                            self.jump_to_branch(&item.0);
                        }
                        self.mode = Mode::Normal;
                        self.input.clear();
                    }
                    KeyCode::Esc => {
                        self.mode = Mode::Normal;
                        self.input.clear();
                    }
                    KeyCode::Backspace => {
                        if self.input.pop().is_none() {
                            self.mode = Mode::Normal;
                        }
                        self.search_selected = 0;
                    }
                    KeyCode::Up => {
                        if self.search_selected > 0 {
                            self.search_selected -= 1;
                        }
                    }
                    KeyCode::Down => {
                        if self.search_selected + 1 < self.search_results().len() {
                            self.search_selected += 1;
                        }
                    }
                    KeyCode::Tab => {}
                    KeyCode::Char(c) => {
                        self.input.push(c);
                        self.search_selected = 0;
                    }
                    _ => {}
