                }
            }
            KeyCode::Char('f') => self.fetch(),
            KeyCode::Char('R') => self.refresh(),
            KeyCode::Down | KeyCode::Char('j') => {
                if self.selected + 1 < total {
                    self.selected += 1;
                    self.branch_sel = 0;
                }
