                if self.selected > 0 {
                    self.selected -= 1;
                    self.branch_sel = 0;
                }
            }
            KeyCode::Char('g') | KeyCode::Home => {
                self.selected = 0;
                self.branch_sel = 0;
            }
            KeyCode::Char('G') | KeyCode::End => {
                self.selected = total.saturating_sub(1);
