                    self.selected = i;
                }
            }
        }
    }
}

impl InputKind {
    fn clone_of(&self) -> InputKind {
        match self {
            InputKind::BranchName => InputKind::BranchName,
            InputKind::Search => InputKind::Search,
        }
    }
}
