        if Some(c.id) == self.data.head_commit {
            return false;
        }
        self.data.branches.iter().any(|b| !b.is_remote() && b.tip == c.id)
    }

    fn delete_branch(&mut self, ci: usize) {
        let _ = git::delete_branch_at(ci);
    }

    fn create_branch(&mut self, name: String) {
        if let Some(RowKind::Commit(ci)) = self.selected_row().map(|r| r.kind) {
            let _ = git::create_branch_at(ci, &name);
        }
    }

    fn checkout(&mut self) {
        if let Some(RowKind::Commit(ci)) = self.selected_row().map(|r| r.kind) {
            match git::checkout_commit(ci) {
                Ok(()) => self.refresh(),
                Err(e) => {
                    self.mode = Mode::Error(format!("{}", e));
                }
            }
        }
    }

    fn fetch(&mut self) {
        match git::fetch_origin() {
            Ok(()) => self.refresh(),
            Err(e) => {
                self.mode = Mode::Error(format!("{}", e));
            }
        }
        self.last_fetch = Instant::now();
    }

    fn refresh(&mut self) {
        if let Ok(data) = git::load() {
            let sel = self.selected_commit_id();
            let files = self.commit_files.clone();
            let graph = graph::build(&data);
            let commit_files = data
                .commits
                .iter()
                .map(|c| git::commit_files(&data, c))
                .collect();
            *self = App {
                data,
                graph,
                commit_files,
                selected: 0,
                branch_sel: 0,
                mode: Mode::Normal,
                input_kind: self.input_kind.clone_of(),
                input: String::new(),
                search_selected: 0,
                error: None,
                confirm_action: None,
                config: self.config.clone(),
                last_refresh: Instant::now(),
                last_fetch: self.last_fetch,
                quit: false,
            };
            self.restore_selection(sel);
            let _ = files;
        }
        self.last_refresh = Instant::now();
    }

    fn selected_commit_id(&self) -> Option<git2::Oid> {
        match self.selected_row().map(|r| r.kind) {
            Some(RowKind::Commit(ci)) => self.data.commits.get(ci).map(|c| c.id),
            _ => None,
        }
    }

    fn restore_selection(&mut self, id: Option<git2::Oid>) {
        if let Some(id) = id {
            if let Some(ci) = self.data.commit_index(&id) {
                if let Some(i) = self.graph.rows.iter().position(|r| r.kind == RowKind::Commit(ci)) {
                    self.selected = i;
                }
            }
        }
    }
}

impl InputKind {
    fn clone_of(&self) -> InputKind {
        match self {
            InputKind::BranchName => InputKind::BranchName,
            InputKind::Search => InputKind::Search,
        }
    }
}
