        let timeout = Duration::from_millis(100);
        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind == ratatui::crossterm::event::KeyEventKind::Press {
                    app.handle_key(key);
                }
            }
        }
        let now = Instant::now();
        if app.config.refresh.auto_refresh
            && now.duration_since(app.last_refresh).as_secs() >= app.config.refresh.refresh_interval
        {
            app.refresh();
        }
        if app.config.refresh.auto_fetch
            && now.duration_since(app.last_fetch).as_secs() >= app.config.refresh.fetch_interval
        {
            let _ = git::fetch_origin();
            app.last_fetch = now;
        }
        if app.quit {
            break;
        }
    }
    Ok(())
}
