    match &app.mode {
        Mode::Help => render_help(f, help_rect(area)),
        Mode::Input => match app.input_kind {
            InputKind::BranchName => {
                render_input_popup(f, input_rect(area), "New Branch Name", &app.input)
            }
            InputKind::Search => {
                let items: Vec<(String, usize, Vec<usize>)> = app.search_results();
                let content = {
                    let n = items.len();
                    if app.input.is_empty() {
                        2
                    } else if n == 0 {
                        2
                    } else {
                        3 + n
                    }
                };
                let r = search_rect(area, content + 2);
                render_search_with(f, r, app, &items);
            }
        },
        _ => {}
    }
    if let Mode::Normal = app.mode {
        if let Some(row) = app.selected_row() {
            if let RowKind::Commit(ci) = row.kind {
                let items = app.branch_items(ci);
                if items.len() > 1 {
                    let w = items
                        .iter()
                        .map(|(n, _)| crate::app::display_width(n))
                        .max()
                        .unwrap_or(0)
                        + 6;
                    let h = items.len() as u16 + 2;
                    let list_h = list.height;
                    let sel_screen_y = {
                        let visible = list.height.saturating_sub(2) as usize;
                        let total = app.graph.rows.len();
                        let offset = if total > visible {
                            app.selected.saturating_sub(visible - 1).min(total - visible)
                        } else {
                            0
                        };
                        list.y + 1 + (app.selected - offset) as u16
                    };
                    let y = (sel_screen_y + 1).min(list.y + list_h.saturating_sub(h));
                    if y + h <= list.y + list_h {
                        let x = area.width.saturating_sub(2 + w);
                        let rect = ratatui::layout::Rect { x, y, width: w, height: h };
                        let sel = app.branch_sel.min(items.len() - 1);
                        let data: Vec<(String, bool)> = items
                            .iter()
                            .enumerate()
                            .map(|(i, (n, _))| (n.clone(), i == sel))
                            .collect();
                        render_branches(f, rect, app, &data);
                    }
                }
            }
        }
    }
}

fn render_search_with(
    f: &mut ratatui::Frame,
    rect: ratatui::layout::Rect,
    app: &App,
    items: &[(String, usize, Vec<usize>)],
) {
    let saved = app.search_items_cache.replace(items.to_vec());
    render_search(f, rect, app);
    app.search_items_cache = saved;
}
